import numpy as np
from scipy.optimize import minimize_scalar


def _basis(x, frequency):
    return np.column_stack([np.ones(len(x)), x, np.sin(frequency*x), np.sin(2*frequency*x)])


def run_node(inputs: dict) -> dict:
    p = inputs['node_00']
    u, v, x = p['u'], p['v1'], p['x']

    def fit(frequency):
        f = _basis(u, frequency)
        coef = np.linalg.lstsq(f, v, rcond=None)[0]
        return f, coef

    def residual(frequency):
        f, coef = fit(frequency)
        return np.mean((f@coef-v)**2)

    frequency = minimize_scalar(residual, bounds=(2.7, 3.8), method='bounded').x
    _, coef = fit(frequency)
    return {'b': _basis(x, frequency)@coef}

